{
  "name": "opencode-prompt-rail",
  "version": "0.1.10",
  "description": "OpenCode Desktop GUI plugin: a recent-prompt rail and a latest-prompt bubble.",
  "type": "module",
  "license": "MIT",
  "author": "Alan468767",
  "homepage": "https://github.com/Alan468767/opencode-prompt-rail#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Alan468767/opencode-prompt-rail.git"
  },
  "bugs": {
    "url": "https://github.com/Alan468767/opencode-prompt-rail/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "desktop",
    "gui",
    "prompt-history",
    "solid-js"
  ],
  "engines": {
    "node": ">=20.19"
  },
  "exports": {
    ".": "./src/index.ts",
    "./server": "./src/index.ts",
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "files": [
    "src",
    "dist"
  ],
  "scripts": {
    "build": "vite build",
    "dev": "vite build --watch",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "2.2.6"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
    "solid-js": "^1.9.0",
    "typescript": "^5.9.0",
    "vite": "^7.0.0",
    "vite-plugin-solid": "^2.11.0"
  }
}
